@use "../functions/escape-svg" as *;
@use "../mixins/border-radius" as *;
@use "../mixins/focus-ring" as *;
@use "../mixins/form-validation" as *;
@use "../mixins/ltr-rtl" as *;
@use "../mixins/tokens" as *;
@use "../config" as *;

// Form validation
//
// Provide feedback to users when form field values are valid or invalid.
// Server-side: `.is-invalid` / `.is-valid` classes work globally.
// Client-side: `:user-invalid` pseudo-class is scoped behind `[data-coreui-validate]`.
// `:user-valid` is scoped behind `[data-coreui-validate~="valid"]` so success styling is opt-in.
// Custom states (e.g., "warning") use only `.is-*` classes.

@mixin form-control-group-validation-state($color, $border-color, $focus-ring-color) {
  --#{$prefix}control-border-color: #{$border-color};
  --#{$prefix}control-focus-border-color: #{$border-color};
  --#{$prefix}control-focus-ring: #{$focus-ring-color};
  --#{$prefix}control-group-icon-color: #{$color};
  --#{$prefix}control-group-action-color: #{$color};
}

// scss-docs-start form-validation-state-mixin
@mixin form-validation-state(
  $state,
  $theme,
  $color: var(--#{$prefix}#{$theme}-fg),
  $tooltip-color: var(--#{$prefix}#{$theme}-contrast),
  $focus-ring-color: var(--#{$prefix}#{$theme}-focus-ring),
  $border-color: var(--#{$prefix}#{$theme}-fg)
) {
  .#{$state}-feedback {
    @include tokens($form-feedback-tokens);

    display: none;
    width: 100%;
    margin-top: var(--#{$prefix}form-feedback-margin-top);
    font-size: var(--#{$prefix}form-feedback-font-size);
    font-style: var(--#{$prefix}form-feedback-font-style, inherit);
    color: $color;
  }

  // The compound variant outweighs .tooltip's own opacity: 0 (0,2,0 vs 0,1,0).
  .tooltip.#{$state}-tooltip,
  .#{$state}-tooltip {
    @include tokens($form-feedback-tokens);

    position: absolute;
    top: 100%;
    z-index: 5;
    display: none;
    max-width: 100%; // Contain to parent when possible
    padding: var(--#{$prefix}tooltip-padding-y, var(--#{$prefix}form-feedback-tooltip-padding-y)) var(--#{$prefix}tooltip-padding-x, var(--#{$prefix}form-feedback-tooltip-padding-x));
    margin-top: .1rem;
    font-size: var(--#{$prefix}tooltip-font-size, var(--#{$prefix}form-feedback-tooltip-font-size));
    line-height: var(--#{$prefix}form-feedback-tooltip-line-height, inherit);
    color: $tooltip-color;
    background-color: var(--#{$prefix}#{$theme}-bg);
    opacity: 1;
    @include border-radius(var(--#{$prefix}tooltip-border-radius, var(--#{$prefix}form-feedback-tooltip-border-radius)));
  }

  @include form-validation-state-selector($state) {
    ~ .#{$state}-feedback,
    ~ .#{$state}-tooltip {
      display: block;
    }
  }

  .form-control {
    @include form-validation-state-selector($state) {
      --#{$prefix}control-border-color: #{$border-color};
      --#{$prefix}control-focus-border-color: #{$border-color};
      --#{$prefix}control-focus-ring: #{$focus-ring-color};

    }
  }

  .form-otp-control {
    @include form-validation-state-selector($state) {
      border-color: $border-color;

      &:focus {
        border-color: $border-color;
        @include focus-ring(true, $color: $focus-ring-color);
      }
    }
  }

  // The state has to reach the group: a custom property set on the control
  // inside it only inherits downwards, never back up to the frame.
  .form-control-group.is-#{$state},
  .is-#{$state} > .form-control-group,
  .form-control-group:has(> .form-control.is-#{$state}),
  .form-control-group:has(> .form-floating > .form-control.is-#{$state}) {
    @include form-control-group-validation-state($color, $border-color, $focus-ring-color);
  }

  @if $state == "invalid" {
    [data-coreui-validate] .form-control-group:has(> .form-control:user-invalid),
    [data-coreui-validate] .form-control-group:has(> .form-floating > .form-control:user-invalid),
    [data-coreui-validate] .form-control-group:has(> select:user-invalid) {
      @include form-control-group-validation-state($color, $border-color, $focus-ring-color);
    }
  } @else if $state == "valid" {
    [data-coreui-validate~="valid"] .form-control-group:has(> .form-control:user-valid),
    [data-coreui-validate~="valid"] .form-control-group:has(> .form-floating > .form-control:user-valid),
    [data-coreui-validate~="valid"] .form-control-group:has(> select:user-valid) {
      @include form-control-group-validation-state($color, $border-color, $focus-ring-color);
    }
  }

  // stylelint-disable selector-no-qualifying-type
  select.form-control,
  .form-control-caret,
  .form-select {
    @include form-validation-state-selector($state) {
      --#{$prefix}control-border-color: #{$border-color};
      --#{$prefix}control-focus-border-color: #{$border-color};
      --#{$prefix}control-focus-ring: #{$focus-ring-color};
    }
  }
  // stylelint-enable selector-no-qualifying-type

  // Range — the validation class lives on .form-range-input, while feedback sits outside
  // the .form-range wrapper, so we use :has() to toggle it.
  // stylelint-disable selector-no-qualifying-type
  .form-range-input,
  input.form-range {
    @include form-validation-state-selector($state) {
      &::-webkit-slider-thumb { background: var(--#{$prefix}#{$theme}-bg); }
      &::-moz-range-thumb { background: var(--#{$prefix}#{$theme}-bg); }

      &:focus-visible {
        &::-webkit-slider-thumb {
          @include focus-ring(true, $color: $focus-ring-color);
        }
        &::-moz-range-thumb {
          @include focus-ring(true, $color: $focus-ring-color);
        }
      }
    }
  }
  // stylelint-enable selector-no-qualifying-type

  .form-range:has(.form-range-input.is-#{$state}) {
    ~ .#{$state}-feedback,
    ~ .#{$state}-tooltip { display: block; }
  }

  .form-control-group.is-#{$state},
  .form-control-group:has(> .is-#{$state}),
  .form-control-group:has(> .form-floating > .is-#{$state}) {
    ~ .#{$state}-feedback,
    ~ .#{$state}-tooltip { display: block; }
  }

  .form-field:has(.form-control-group.is-#{$state}),
  .form-field:has(.form-control-group > .is-#{$state}),
  .form-field:has(.form-control-group > .form-floating > .is-#{$state}) {
    .#{$state}-feedback,
    .#{$state}-tooltip { display: block; }
  }

  @if $state == "invalid" {
    [data-coreui-validate] {
      .form-control-group:has(> :user-invalid),
      .form-control-group:has(> .form-floating > :user-invalid) {
        ~ .invalid-feedback,
        ~ .invalid-tooltip { display: block; }
      }

      .form-field:has(.form-control-group > :user-invalid),
      .form-field:has(.form-control-group > .form-floating > :user-invalid) {
        .invalid-feedback,
        .invalid-tooltip { display: block; }
      }
    }
  } @else if $state == "valid" {
    .form-control-group.is-invalid,
    .form-control-group:has(.is-invalid) {
      ~ .valid-feedback,
      ~ .valid-tooltip { display: none; }
    }

    .form-field:has(.form-control-group.is-invalid),
    .form-field:has(.form-control-group .is-invalid) {
      .valid-feedback,
      .valid-tooltip { display: none; }
    }
  }

  @if $state == "invalid" {
    [data-coreui-validate] .form-field:has(.input-group :user-invalid) {
      .invalid-feedback,
      .invalid-tooltip {
        display: block;
      }
    }
  } @else if $state == "valid" {
    [data-coreui-validate~="valid"] .form-field:has(.input-group :user-valid) {
      .valid-feedback,
      .valid-tooltip {
        display: block;
      }
    }
  }

  .input-group {
    > .autocomplete:focus-within,
    > .date-picker:focus-within,
    > .time-picker:focus-within,
    > .form-control-group:focus-within,
    > .form-multi-select:focus-within,
    > .form-control:focus,
    > .form-select:focus,
    > .form-floating:focus-within {
      @include form-validation-state-selector($state) {
        @if $state == "valid" {
          z-index: 3;
        } @else if $state == "invalid" {
          z-index: 4;
        }
      }
    }
  }
}
// scss-docs-end form-validation-state-mixin

@layer forms {
  // scss-docs-start form-validation-states-loop
  @each $state, $data in $form-validation-states {
    @include form-validation-state($state, $data...);
  }
  // scss-docs-end form-validation-states-loop
}
